module.exports = /*#__PURE__*/JSON.parse('[{"id":"cand_econ_1","portfolioId":"economy","name":"Dr. Henrique Meireles Neves","age":63,"competence":92,"loyalty":70,"integrity":88,"popularity":60,"experience":90,"ideologyLean":"Ortodoxo / Mercado Financeiro","partyAffiliation":"Independente (Técnico)","bio":"Ex-presidente do Banco Central e banqueiro internacional. Tem aprovação quase unânime da Faria Lima e agrada o mercado, mas é rígido contra gastos sociais.","effectsSummary":"Reduz inflação e risco-país; Mercado +15%, Trabalhadores -8%."},{"id":"cand_econ_2","portfolioId":"economy","name":"Profª Elena Tavares","age":52,"competence":86,"loyalty":88,"integrity":90,"popularity":72,"experience":78,"ideologyLean":"Desenvolvimentista Social","partyAffiliation":"PTP (Trabalhista)","bio":"Economista da Unicamp com foco em combate à desigualdade, industrialização e investimentos públicos indutores.","effectsSummary":"Aumenta programas sociais e consumo; Trabalhadores +14%, Mercado -12%."},{"id":"cand_econ_3","portfolioId":"economy","name":"Dep. Valdemar Nogueira","age":58,"competence":60,"loyalty":65,"integrity":52,"popularity":45,"experience":82,"ideologyLean":"Fisiológico Pragmático","partyAffiliation":"BCI (Centrão)","bio":"Político veterano com controle direto sobre 45 deputados do Centrão. Sua nomeação garante a aprovação de reformas no Congresso, mas atrai investigações da PF.","effectsSummary":"Traz +45 votos no plenário; Percepção de corrupção +10."},{"id":"cand_just_1","portfolioId":"justice","name":"Dra. Carmen Lúcia Brandão","age":56,"competence":90,"loyalty":75,"integrity":95,"popularity":78,"experience":85,"ideologyLean":"Garantista Constitucional","partyAffiliation":"Independente (Jurista)","bio":"Ex-procuradora-geral com reputação ilibada no STF. Defende direitos humanos, garantias individuais e rigor em auditorias.","effectsSummary":"Aumenta confiança institucional e independência judiciária."},{"id":"cand_just_2","portfolioId":"justice","name":"Delegado Mauro Alencar","age":49,"competence":82,"loyalty":80,"integrity":78,"popularity":82,"experience":72,"ideologyLean":"Lei & Ordem / Punitivista","partyAffiliation":"POR (Ordem e Segurança)","bio":"Famoso por operações ostensivas contra o crime organizado e desarticulação de facções. Adorado pela Bancada da Bala e classe média.","effectsSummary":"Reduz criminalidade; Militares +15%, Direitos Humanos -10%."},{"id":"cand_health_1","portfolioId":"health","name":"Dra. Margareth Dalcolmo","age":64,"competence":94,"loyalty":75,"integrity":92,"popularity":85,"experience":88,"ideologyLean":"Sanitarista Científica","partyAffiliation":"Independente (Acadêmica)","bio":"Pneumologista e pesquisadora da Fiocruz. Respeitada internacionalmente, defende vacinação universal e fortalecimento da rede pública de hospitais.","effectsSummary":"Reduz filas do SUS; Aprovação popular +10%."},{"id":"cand_health_2","portfolioId":"health","name":"Dep. Arthur Barros","age":50,"competence":58,"loyalty":80,"integrity":58,"popularity":48,"experience":70,"ideologyLean":"Político do Centrão","partyAffiliation":"PLP (Liberal Popular)","bio":"Médico do interior e articulador político. Controla o repasse de verbas de hospitais filantrópicos no Congresso.","effectsSummary":"Traz +35 votos na Câmara; Risco moderado de desvios."},{"id":"cand_edu_1","portfolioId":"education","name":"Prof. Cristóvão Buarque","age":68,"competence":90,"loyalty":75,"integrity":92,"popularity":74,"experience":92,"ideologyLean":"Humanista / Ensino Básico","partyAffiliation":"MSD (Social Democrata)","bio":"Ex-reitor de universidade federal e idealizador de bolsas de incentivo escolar para crianças e jovens.","effectsSummary":"Melhora alfabetização e qualidade do ensino; Professores +18%."},{"id":"cand_edu_2","portfolioId":"education","name":"Pastor Paulo Guedes Júnior","age":47,"competence":65,"loyalty":85,"integrity":75,"popularity":62,"experience":60,"ideologyLean":"Conservador Tradicionalista","partyAffiliation":"Bancada Evangélica","bio":"Líder religioso e pedagogo com forte penetração nas bancadas conservadoras. Defende valores tradicionais e escolas cívico-militares.","effectsSummary":"Evangélicos +20%, Classe Média Progressista -15%."},{"id":"cand_infra_1","portfolioId":"infra","name":"Eng. Tarcísio Vilela","age":53,"competence":90,"loyalty":70,"integrity":82,"popularity":80,"experience":85,"ideologyLean":"Infraestrutura Pesada / Concessões","partyAffiliation":"Independente (Militar da Reserva)","bio":"Ex-oficial de engenharia do Exército. Focado em leilões rodoviários, privatização de portos e conclusão rápida de obras inacabadas.","effectsSummary":"Aumenta eficiência logística; Agronegócio +15%, Empresários +12%."},{"id":"cand_infra_2","portfolioId":"infra","name":"Dep. Gilberto Kassab","age":59,"competence":72,"loyalty":90,"integrity":65,"popularity":50,"experience":88,"ideologyLean":"Pragmático Articulador","partyAffiliation":"BCI (Centrão)","bio":"Mestre da articulação partidária. Conhece cada prefeitura e deputado do país.","effectsSummary":"Traz estabilidade parlamentar e +40 deputados fiéis."},{"id":"cand_foreign_1","portfolioId":"foreign","name":"Embaixador Celso Amorim Silva","age":71,"competence":94,"loyalty":82,"integrity":90,"popularity":68,"experience":95,"ideologyLean":"Multilateralismo / Sul Global","partyAffiliation":"Diplomata de Carreira","bio":"Veterano do Itamaraty. Especialista em acordos do BRICS, Mercosul e abertura de novos mercados na Ásia e África.","effectsSummary":"Aumenta exportações agrícolas e industriais; Relações exteriores +20."},{"id":"cand_agri_1","portfolioId":"agriculture","name":"Tereza Cristina Dias","age":58,"competence":92,"loyalty":75,"integrity":85,"popularity":78,"experience":88,"ideologyLean":"Agronegócio Exportador","partyAffiliation":"Frente Parlamentar da Agropecuária","bio":"Engenheira agrônoma e líder ruralista. Abre mercados internacionais e destrava crédito rural para produtores de grãos e carnes.","effectsSummary":"Agronegócio +25%; Ambientalistas -15%."},{"id":"cand_env_1","portfolioId":"environment","name":"Marina Silva Albuquerque","age":62,"competence":95,"loyalty":78,"integrity":98,"popularity":82,"experience":90,"ideologyLean":"Sustentabilidade & Clima","partyAffiliation":"Rede Ambientalista","bio":"Ícone mundial da proteção ambiental. Combate o desmatamento ilegal, atrai fundos internacionais de preservação e promove a transição verde.","effectsSummary":"Fundos internacionais +R$ 5 bi; Agronegócio reclama de burocracia ambiental."},{"id":"cand_mines_1","portfolioId":"mines_energy","name":"Dr. Jean Paul Prates","age":55,"competence":85,"loyalty":82,"integrity":80,"popularity":55,"experience":84,"ideologyLean":"Segurança Energética & Petróleo","partyAffiliation":"PTP (Trabalhista)","bio":"Especialista em regulação de petróleo, gás natural e energias renováveis eólicas marítimas.","effectsSummary":"Estabiliza preços de combustíveis e atrai investimentos em energia."},{"id":"cand_defense_1","portfolioId":"defense","name":"General Paulo Sérgio Nogueira","age":65,"competence":88,"loyalty":80,"integrity":90,"popularity":70,"experience":90,"ideologyLean":"Institucionalista Militar","partyAffiliation":"Forças Armadas","bio":"Ex-comandante do Exército com perfil conciliador. Garante a lealdade dos quartéis à Constituição e moderniza equipamentos de defesa.","effectsSummary":"Militares +20%; Previne crises institucionais com as Forças Armadas."}]');

